    data = list(map(int, sys.stdin.read().strip().split()))
    it = iter(data)
    T = next(it, 0)
    out_lines = []
    for _ in range(T):
        n = next(it)
        a = [next(it) for _ in range(n)]

        # 特判 n = 1
        if n == 1:
            out_lines.append("0")
            continue

        mn = min(a)
        mx = max(a)

        # 候选1: a1 - an
        ans = a[0] - a[-1]

